client_script:
frappe.web_form.after_load = () => {
    setTimeout(() => {
        /* RENAME collapse-row BUTTON (LIVE)   */
        function renameCollapseButtons() {
            document.querySelectorAll('.btn.grid-collapse-row').forEach(btn => {
                if (btn.textContent.trim() !== 'Add to Row') {
                    btn.textContent = 'Add to Row';
                }
            });
        }
        // Call once on initial load
        renameCollapseButtons();
        // Observe DOM for new buttons
        const observer = new MutationObserver(() => {
            renameCollapseButtons();
        });
        observer.observe(document.body, { childList: true, subtree: true });
        
        let child_table_fieldname = "anticipatory_action_details";
        let grid_field = frappe.web_form.fields_dict[child_table_fieldname];
        
        if (grid_field && grid_field.grid) {
            // Override the add_new_row method
            let original_add_new_row = grid_field.grid.add_new_row.bind(grid_field.grid);
            
            grid_field.grid.add_new_row = function(idx, callback, show_dialog) {
                // Remove any existing click listeners
                $(document).off('click.close_row');
                
                // Close any currently open grid rows by toggling their form
                if (grid_field.grid.grid_rows) {
                    grid_field.grid.grid_rows.forEach(function(grid_row) {
                        if (grid_row.row && grid_row.row.is_open && grid_row.row.is_open()) {
                            grid_row.toggle_view(false); // Close the row
                        }
                    });
                }
                
                // Small delay to ensure close completes
                setTimeout(() => {
                    // Add row collapsed (show_dialog=false)
                    let row = original_add_new_row(idx, callback, false);
                    
                    setTimeout(() => {
                        // Find the newly added grid row and open it
                        let new_grid_row = grid_field.grid.grid_rows[grid_field.grid.grid_rows.length - 1];
                        
                        if (new_grid_row) {
                            new_grid_row.toggle_view(true); // Open the new row
                            
                            // Get the actual DOM element for click-outside detection
                            let $last_row = $(grid_field.grid.wrapper).find(".grid-body .grid-row").last();
                            
                            // CLICK OUTSIDE TO CLOSE
                            $(document).on('click.close_row', function(e) {
                                if (!$.contains($last_row[0], e.target)) {
                                    new_grid_row.toggle_view(false);
                                    $(document).off('click.close_row');
                                }
                            });
                        }
                        
                        // Re-bind Cancel button logic for new row
                        if (typeof convertDeleteToCancel === 'function') {
                            convertDeleteToCancel();
                        }
                    }, 100);
                }, 100);
                
                return undefined;
            };
        }
    }, 500);
};

